$('#connect').onclick=()=>action(connect);$('#account').onchange=()=>action(async()=>{const selected=$('#account').value;await invalidateAccess();account=selected;await permissions();await render();});$('#switch').onclick=()=>action(async()=>{if(!provider)throw Error('Connect a wallet first');await provider.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x'+session.chainId.toString(16)}]});await networkChanged();await authenticate();if(auth&&org?.ready){$('#wallet-dialog').close();await navigate(workspaceReturn||'/workspace',!!workspaceReturn);}});
$('#invoice').oninput=()=>{requestId=crypto.randomUUID();};$('#invoice').onsubmit=event=>{event.preventDefault();action(async()=>{if(!caps.canIssue)throw Error('Connect the authorized invoice signer');await showDraft(await api('draft',{...Object.fromEntries(new FormData(event.target)),org:org.org,requestId}));});};$('#reviewed').onchange=controls;$('#resume-pdf').onchange=()=>action(async()=>{const file=$('#resume-pdf').files[0];if(!file||file.size>5*1024*1024)throw Error('Choose the exact downloaded PDF, up to 5 MB');await previewBytes(await file.arrayBuffer());});
$('#register-name').onclick=()=>action(async()=>{const epoch=accessEpoch,original=draft;draft=await api('registration',{id:original.id,...(session.documentStorage==='none'?{pdfBase64:draftPDFBase64}:{})});renderProgress();if(draft.registration?.status==='confirmed')return;const prepared=draft.registration;let hash;try{hash=await requestWallet('transaction',()=>submit(provider,account,prepared.tx,{to:prepared.to,data:prepared.data}));}catch(error){if(Number(error.code)===4001&&epoch===accessEpoch)draft=await api('registration/rejected',{id:original.id,code:4001});throw error;}storage.set('hir-pending-name-registration',JSON.stringify({id:original.id,org:original.org,account:original.policy.issuer,ledger:session.ledger,hash}));if(epoch!==accessEpoch)throw Error('Name registration was submitted for the original wallet. Reconnect it and recheck; do not register again.');draft=await api('registration/hash',{id:original.id,hash});storage.remove('hir-pending-name-registration');renderProgress();});
$('#recheck-name').onclick=()=>action(async()=>{draft=await api('registration/recheck',{id:draft.id});renderProgress();});$('#record-name-hash').onclick=()=>action(async()=>{const hash=$('#name-hash').value.trim();if(!/^0x[a-fA-F0-9]{64}$/.test(hash))throw Error('Enter the public registration hash');draft=await api('registration/hash',{id:draft.id,hash});renderProgress();});
$('#sign').onclick=()=>action(async()=>{const signature=await requestWallet('signature',()=>signInvoice(provider,account,draft,session));draft=await api('signature',{id:draft.id,signature,...(session.documentStorage==='none'?{pdfBase64:draftPDFBase64}:{})});renderProgress();});
$('#publish').onclick=()=>action(async()=>{const epoch=accessEpoch,original=draft;const prepared=await api('publication',{id:original.id,account,...(session.documentStorage==='none'?{pdfBase64:draftPDFBase64}:{})});if(epoch!==accessEpoch)throw Error('Wallet changed');draft=prepared;if(draft.intent?.hash){renderProgress();return;}let hash;try{hash=await requestWallet('transaction',()=>submit(provider,account,prepared.intent.tx,{to:session.ledger,data:prepared.intent.data}));}catch(error){if(Number(error.code)===4001&&epoch===accessEpoch)draft=await api('publication/rejected',{id:original.id,code:4001});throw error;}const pending={id:original.id,org:original.org,account:original.policy.issuer,ledger:session.ledger,hash};storage.set('hir-pending-publication',JSON.stringify(pending));if(epoch!==accessEpoch)throw Error('Transaction submitted for the original signer. Reconnect that wallet to recover it; do not submit again.');draft.intent.hash=hash;renderProgress();draft=await api('publication/hash',{id:original.id,hash});storage.remove('hir-pending-publication');renderProgress();});
$('#recheck').onclick=()=>action(async()=>{draft=await api('publication/recheck',{id:draft.id});renderProgress();await refreshWorkspace();});$('#record-hash').onclick=()=>action(async()=>{const hash=$('#transaction-hash').value.trim();if(!/^0x[a-fA-F0-9]{64}$/.test(hash))throw Error('Enter the public transaction hash');draft=await api('publication/hash',{id:draft.id,hash});renderProgress();});
async function poll(){if(platform?.registeredHierarchy&&draft?.registration?.hash&&!['confirmed','failed'].includes(draft.registration.status)){try{draft=await api('registration/recheck',{id:draft.id});renderProgress();controls();}catch(error){notice(error.message,true);}}if(draft?.intent?.hash&&!['confirmed','failed'].includes(draft.status)){try{draft=session.documentStorage==='none'?await api('publication/recheck',{id:draft.id}):await api('draft/'+draft.id);renderProgress();controls();if(draft.status==='confirmed')await refreshWorkspace();}catch(error){notice(error.message,true);}}setTimeout(poll,4000);}
try{session=await api('session');platform=await api('platform');await render();poll();}catch(error){notice(error.shortMessage||error.message,true);}

function refreshModuleState(){
 const headerAction=$('.site-header .header-cta');if(headerAction){headerAction.hidden=page==='verify';const connected=page!=='home'&&!!auth;headerAction.textContent=connected?'Wallet · '+auth.account.slice(0,6)+'…'+auth.account.slice(-4):'Set up organization';headerAction.classList.toggle('wallet-status',connected);if(connected)headerAction.dataset.action='wallet';else delete headerAction.dataset.action;}

 if(page==='identity'){const set=(id,value,pass=false)=>{const e=$('#'+id);if(e){e.textContent=value;e.classList.toggle('pass',pass);}};set('identity-name-state',org?org.org:'Not checked',!!org);set('identity-wallet-state',auth?'Signed in · '+auth.account.slice(0,6)+'…'+auth.account.slice(-4):'Not signed in',!!auth);const allowed=!!auth&&(caps.canConfigure||caps.canIssue||caps.canAdminister);set('identity-permission-state',allowed?'Authority checked':'Not checked',allowed);}
 if(page==='review'&&$('#setup-operation-state')){const phase=lastActionError?.code===4001?'declined':setupPhase==='failed'?'failed':setupIntent?.hash?'pending':setupIntent?setupIntent.status==='prepared'?'prepared':walletAction?'wallet':'ambiguous':undefined;$('#setup-operation-state').innerHTML=renderOperationState({phase,hash:setupIntent?.hash,error:lastActionError?.message,purpose:setupIntent?setupOperation(setupIntent.purpose,org?.org).purpose:undefined});$('#setup-recovery').hidden=!setupIntent||!!setupIntent.hash||setupIntent.status==='prepared';}
 if(!draft||!$('#final')||$('#final').hidden)return;
 const registered=!platform.registeredHierarchy||draft.registration?.status==='confirmed',signed=!!draft.signature,published=draft.status==='confirmed';
 $('#register-name').hidden=registered;$('#sign').hidden=signed||!registered;$('#publish').hidden=published||!signed;
 for(const [id,complete,active]of [['name-registration',registered,!registered],['pdf-approval-step',signed,registered&&!signed],['publication-step',published,signed&&!published]]){const e=$('#'+id);e.classList.toggle('complete',complete);e.classList.toggle('active',active);}
 $('#name-state-chip').textContent=registered?'Confirmed':draft.registration?.hash?'Confirmation pending':'Wallet transaction';$('#signature-state-chip').textContent=signed?'Signed':'Message signature';$('#publication-state-chip').textContent=published?'Confirmed':draft.intent?.hash?'Confirmation pending':'Wallet transaction';
 const intent=!registered?draft.registration:draft.intent;const phase=lastActionError?.code===4001?'declined':draft.registration?.error||draft.error?.toLowerCase().includes('revert')?'failed':intent?.hash&&!published?'pending':intent&&!intent.hash?walletAction?'wallet':'ambiguous':walletAction?'wallet':undefined;
 $('#invoice-operation-state').innerHTML=renderOperationState({phase,hash:intent?.hash,error:lastActionError?.message||draft.registration?.error||draft.error,purpose:!registered?'Register invoice ENS name':!signed?'Approve this exact PDF (message signature)':'Publish invoice evidence',signature:registered&&!signed});
}
